Get-WmiObject -Class Win32_Product | Where-Object {$_.Name -like "*Office*"} | ForEach-Object {$_.Uninstall()}; $office = Get-ItemProperty "HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*" | Where-Object {$_.DisplayName -like "*Office*"}; $office | ForEach-Object { Start-Process "cmd.exe" -ArgumentList "/c $($_.UninstallString)" -Wait }; reg add "HKLM\SOFTWARE\Policies\Microsoft\office\16.0\common\officeupdate" /v enableautomaticupdates /t REG_DWORD /d 0 /f; reg add "HKLM\SOFTWARE\Microsoft\Office\ClickToRun\Configuration" /v UpdatesEnabled /t REG_SZ /d False /f; Stop-Service ClickToRunSvc -Force -ErrorAction SilentlyContinue; Set-Service ClickToRunSvc -StartupType Disabled -ErrorAction SilentlyContinue
